import { createFileRoute } from '@tanstack/react-router';
import { ProjectDetail } from '../slots/defs/projectDetail';

// Opening a project is a CHILD ROUTE, not a flag: this new file renders at /projects/$projectId.
// The page itself holds no feature content — it renders the project-detail slot, which the project's
// invoices (and anything added later) fill from their own files.
export const Route = createFileRoute('/projects/$projectId')({
  component: ProjectDetailPage,
});

function ProjectDetailPage() {
  const { projectId } = Route.useParams();
  return (
    <section data-testid="project-detail">
      <ProjectDetail.Slot projectId={Number(projectId)} />
    </section>
  );
}
=== projectDetail.ts ===
import { defineSlot } from '../Slot';

/**
 * A project's detail region. The project-detail route renders this once; features (its invoices,
 * and anything added later) fill it with `ProjectDetail.fill(...)`, each panel querying for itself.
 * The context is the project's id, so a contribution can scope its own data to that project.
 */
export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
=== open.slot projects ===
import { Link } from '@tanstack/react-router';
import { ProjectRowActions } from '../../slots/defs/projectRowActions';

// The link that opens a project's detail page — its own file, filling the project-row-actions slot.
// Drilling in is a child route (/projects/$projectId), reached by this Link; the list is not edited
// to know about it. Carries data-testid="project-open-<id>" (the test contract).
export const contribution = ProjectRowActions.fill({
  order: 10,
  Component: ({ projectId }) => (
    <Link
      to="/projects/$projectId"
      params={{ projectId: String(projectId) }}
      data-testid={`project-open-${projectId}`}
    >
      Open
    </Link>
  ),
});
=== ProjectsPage ===
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import type { Client } from '../clients/ClientsPage';
import { ProjectRowActions } from '../../slots/defs/projectRowActions';

// A project as the server returns it: it carries the client's NAME so the list shows the name, not
// the id. project.clientId is the id the form's select submits.
export type Project = { id: number; name: string; clientId: number; clientName: string };

// The projects page: the whole list of projects plus the form to add one and pick its client.
// Server data is read with useQuery (['projects'] for the list, ['clients'] — the SAME key the
// clients feature owns — for the select options) and changed with useMutation + invalidateQueries.
// The only useState here is the fields the user is currently filling in (rule 4).
export function ProjectsPage() {
  const queryClient = useQueryClient();
  const projects = useQuery({
    queryKey: ['projects'],
    queryFn: () => getJson<Project[]>('/api/projects'),
  });
  const clients = useQuery({
    queryKey: ['clients'],
    queryFn: () => getJson<Client[]>('/api/clients'),
  });

  const [name, setName] = useState('');
  const [clientId, setClientId] = useState('');

  const create = useMutation({
    mutationFn: () => postJson<Project>('/api/projects', { name, clientId: Number(clientId) }),
    onSuccess: () => {
      setName('');
      setClientId('');
      void queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
  });

  const rows = projects.data ?? [];
  const clientOptions = clients.data ?? [];

  return (
    <section data-testid="projects">
      <form
        data-testid="project-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!name.trim() || !clientId) {
            return;
          }
          create.mutate();
        }}
      >
        <input
          data-testid="project-form-name"
          placeholder="Project name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <select
          data-testid="project-form-client"
          value={clientId}
          onChange={(e) => setClientId(e.target.value)}
        >
          <option value="">Select a client</option>
          {clientOptions.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
        <button data-testid="project-form-submit" type="submit">
          Add project
        </button>
      </form>

      {rows.length === 0 ? (
        <p data-testid="projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="projects-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Client</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {rows.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
                <td data-testid="project-client">{p.clientName}</td>
                <td>
                  <ProjectRowActions.Slot projectId={p.id} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

